	"f848a69e": "Aby zweryfikować Twoje konto, musimy potwierdzić jego autentyczność. Jeśli Twoja nazwa użytkownika nie jest wspomniana na wskazanej oficjalnej stronie, nie możemy zweryfikować konta.",
