	"i6ef95ec": "ankietę",
	"j94e995e": "Twój ostatni wniosek o weryfikację konta został odrzucony. Kolejny wniosek możesz złożyć po upływie 30 dni.",
	"da458d6c": "W ciągu ostatnich 30 dni złożyłeś/aś wniosek o weryfikację konta, który odrzucono. Spróbuj ponownie w innym terminie.",
	"j4ed9f0e": "Złożyłeś/aś wniosek o weryfikację konta. Wkrótce skontaktujemy się z Tobą.",
	"b1ade780": "Twoje konto jest zbyt nowe. Poczekaj, aż Twoje konto będzie mieć co najmniej 7 dni, i spróbuj ponownie.",
