	"aaafffda": "Wyciszono powiadomienia",
	"afdf29b8": "Filtr jakości",
	"da19d878": "Możesz odfiltrować wybrane treści, takie jak powtarzające się lub automatyczne wpisy. Nie dotyczy to powiadomień z kont, które obserwujesz, ani kont, z którymi ostatnio wchodzono w interakcję.",
