	"a2197726": "Zarządzaj bezpieczeństwem swojego konta.",
	"i36dcc3e": "Pomóż chronić swoje konto przed dostępem nieupoważnionych osób dzięki dodatkowej metodzie weryfikacji logowania (oprócz hasła do serwisu X). Może to być wiadomość SMS, aplikacja uwierzytelniająca lub klucz zabezpieczeń.",
	"ead60eb8": "Dodatkowa ochrona hasłem",
	"gfaf9a4a": "Ochrona resetowania hasła",
	"h3cc8462": "W celu zwiększenia ochrony poprosimy Cię o potwierdzenie adresu e-mail lub numeru telefonu, gdy będziesz resetować hasło do serwisu X.",
	"b4bbdeb4": "Klucz dostępu",
	"fe8aeb88": "Klucze dostępu oferują dodatkową ochronę, którą można powiązać ze swoimi danymi biometrycznymi.",
	"dc096238": "Prześlij kopię dokumentu tożsamości, aby potwierdzić autentyczność swojego konta. Twoje dane osobowe posłużą nam jedynie w celu potwierdzenia Twojej tożsamości i dołożymy wszelkich starań, aby zadbać o ich bezpieczeństwo.",
	"a999cb72": "Zapisz zmiany na koncie",
	"dec3c9b8": "Hasło",
	"b929aa74": "Aby zapisać zmiany w ustawieniach konta, wprowadź ponownie hasło do serwisu X.",
