	"b02df748": "Zarządzaj ustawieniami bezpieczeństwa i przeglądaj dane dotyczące korzystania z Twojego konta, w tym informację o tym, jakie aplikacje powiązane są z Twoim kontem.",
	"g2841de4": "Zobacz dane dotyczące czasu, w którym logowałeś/aś się na swoje konto i powiązanych aplikacji.",
