	"b06f5d36": "Twoja aktywność w serwisie X",
	"fd807e78": "Odbiorcy, multimedia i oznaczanie",
	"a9ff473c": "Określ, jakie informacje na Twój temat mogą widzieć inni użytkownicy serwisu X.",
