	"ab125232": "Zarządzaj wyciszonymi i zablokowanymi kontami, słowami i powiadomieniami.",
	"cc950d94": "Zdecyduj o tym, kto może wysłać do Ciebie prywatne wiadomości.",
	"fe37f854": "Określ, kto może zobaczyć informacje o Pokojach, których jesteś słuchaczem",
	"ab987f3c": "Dostosuj swoje ustawienia odkrywania i zarządzaj kontaktami, które zaimportowałeś/aś.",
