	"i83cab8a": "Personalizacja i udostępnianie danych",
	"e338a794": "Zarządzaj reklamami w serwisie X.",
	"c05e8024": "Zarządzaj plikami cookie w serwisie X.",
	"d29d59d0": "Zarządzaj możliwościami używania przez serwis X danych o Twojej aktywności poza serwisem X, na przykład informacji o odwiedzanych przez Ciebie witrynach internetowych, w celu personalizacji Twojego środowiska.",
	"c981a36c": "Zezwalaj na personalizację Twoich ustawień na podstawie Twojej pozostałej aktywności, np. na urządzeniach, za pomocą których nie logujesz się do serwisu X.",
	"eb0cc786": "Zezwalaj na udostępnianie dodatkowych informacji partnerom biznesowym serwisu X.",
	"dd533318": "Zarządzaj danymi lokalizacji, które wykorzystujemy, aby lepiej dostosowywać wybierane dla Ciebie treści.",
	"bd0646a0": "Dowiedz się więcej o ochronie prywatności w serwisie X",
	"a607862a": "Polityka prywatności",
	"g5925628": "Kontakt",
	"dd6012f8": "Centrum prywatności",
	"f644b748": "Zdecyduj, kto może odpowiadać na Twoje wpisy i odfiltrowane odpowiedzi.",
	"ff4b3818": "Grok i współpracownicy zewnętrzni",
	"i586f3e0": "Zezwalaj firmie xAI na używanie Twoich publicznych danych oraz interakcji, danych wejściowych i wyników na potrzeby szkolenia Groka i dostrajania jego działania",
	"df3171d4": "Zarządzaj lokalizacją skojarzoną z Twoim kontem",
	"d8492604": "Po wybraniu tej opcji Twoje wpisy i inne informacje dotyczące Twojego konta będą widoczne tylko dla osób, które Cię obserwują.",
	"if050fae": "Chroń swoje filmy",
	"b7ed5f6e": "Wybranie tego ustawienia spowoduje, że filmy znajdujące się w Twoich wpisach domyślnie nie będą dostępne do pobrania. To ustawienie ma zastosowanie do wpisów tworzonych po wybraniu go i nie dotyczy wcześniej utworzonych wpisów.",
	"dbb51952": "Chronić Twoje wpisy?",
	"de735de6": "Odpowiedzi będą widoczne tylko dla Twoich obserwujących w serwisie X.",
	"c5d4192a": "Chroń",
	"d9ddba70": "Grupy dyskusyjne są publiczne, dlatego włączenie ochrony konta spowoduje ukrycie Twoich poprzednich wpisów. Nie będziesz również mieć możliwości publikowania w grupie dyskusyjnej, dopóki Twoje konto nie będzie znowu publiczne.",
	"f527b322": "Chroń moje konto",
	"d165c992": "Każdy może Cię oznaczać",
	"ea339390": "Tylko osoby, które obserwujesz, mogą Cię oznaczać",
	"e3a761ee": "Wył.",
	"d3a2bde8": "Zobacz informacje dotyczące Twojego konta, pobierz archiwum swoich danych lub dowiedz się, w jaki sposób dezaktywować konto",
	"idca4742": "Zobacz informacje dotyczące Twojego konta, takie jak Twój numer telefonu czy adres e-mail.",
	"b6ded35e": "W dowolnym momencie możesz zmienić hasło.",
	"cce24bf4": "Dowiedz się, jakie informacje dotyczące Twojego konta przechowujemy.",
	"i203df96": "Dowiedz się, w jaki sposób dezaktywować konto.",
	"a61ed23a": "Oznacz multimedia, które publikujesz, jako zawierające potencjalnie nieodpowiednie materiały",
	"ae27c454": "Po wybraniu tej opcji zdjęcia i filmy dołączone do Twoich wpisów będą oznaczone jako nieodpowiednie dla użytkowników, którzy nie chcą widzieć nieodpowiednich treści.",
	"fc1d217c": "Wyświetl multimedia, które mogą zawierać nieodpowiednie treści",
	"j018f2a2": "Ustawienia funkcji Odkryj",
	"h1ef00dc": "Ustawienia wyszukiwania",
	"ib3357a6": "Spersonalizowane reklamy",
	"f2f9628e": "Reklamy w serwisie X są zawsze personalizowane na podstawie Twojej aktywności w serwisie X. Po włączeniu tego ustawienia reklamy w serwisie X i poza nim będą personalizowane na podstawie Twojej aktywności w serwisie X i pozostałej aktywności online oraz informacji od naszych partnerów.",
	"b5fe50fc": "Kategorie reklam",
	"c31a2ea6": "Za pomocą poniższych ustawień możesz zdecydować o kategoriach reklam, które będziesz widzieć. Aby widzieć mniej reklam z wybranej kategorii, usuń zaznaczenie.",
	"if996630": "Hazard",
	"a9ed7774": "Zezwalaj na używanie informacji o miejscach w Internecie, w których przeglądasz treści z serwisu X",
	"e2d61838": "To ustawienie umożliwia serwisowi X zbieranie informacji o Twoich wizytach w innych witrynach internetowych, które mogą zawierać treści z serwisu X, np. osadzone osie czasu. Pozwala nam to ulepszać serwis X dla Ciebie, na przykład przez personalizację Twojego środowiska. W historii przeglądania Internetu nigdy nie będzie przechowywane Twoje imię i nazwisko, adres e-mail ani numer telefonu. ",
	"c966aaf4": "Te informacje o odwiedzanych stronach nie są przechowywane ani wykorzystywane, gdy przebywasz w niektórych krajach.",
	"e8313b32": "Na pewno? Po wyłączeniu tej opcji nie można jej włączyć ponownie w tym kraju.",
	"f1d46fd6": "Tak, na pewno",
	"f6c8ccc8": "Personalizuj na podstawie dodatkowych informacji",
	"ed012c88": "Personalizacja Twojego konta w serwisie X zawsze jest wykonywana na podstawie podanych przez Ciebie informacji oraz urządzeń używanych w celu logowania do serwisu X. Po włączeniu tej opcji serwis X może powiązać Twoje konto również z innymi danymi dotyczącymi Ciebie pośrednio, takimi jak urządzenia i przeglądarki, które nie były przez Ciebie używane w celu logowania się do serwisu X, lub adresy e-mail i numery telefonów podobne do tych powiązanych z Twoim kontem.",
	"d3c20d80": "Zezwalaj na udostępnianie dodatkowych informacji naszym partnerom biznesowym",
	"f1c0d09c": "Zawsze udostępniamy naszym partnerom informacje, które pomagają nam obsługiwać oraz rozwijać produkty i usługi serwisu X. Wybranie tej opcji umożliwia nam udostępnianie naszym partnerom dodatkowych informacji, które pomagają podnosić jakość naszych usług, między innymi poprzez lepsze dopasowywanie do Ciebie treści reklamowych na innych stronach i w innych aplikacjach.",
	"dc20d918": "Personalizuj na podstawie odwiedzanych miejsc",
	"af7d89e6": "Korzystamy z pewnych informacji, takich jak miejsce rejestracji lub Twoja obecna lokalizacja, aby lepiej dostosowywać wybierane dla Ciebie treści. To ustawienie pozwoli nam dobierać treści również na podstawie innych odwiedzonych przez Ciebie miejsc.",
	"f2b23062": "Dostępność, wyświetlanie i języki",
	"fa76d7dc": "Zdecyduj, jakie treści chcesz widzieć w serwisie X.",
	"j7a15010": "Zarządzaj różnymi aspektami konta w serwisie X, w tym kontrastem kolorów i zakresem ruchu.",
	"a257ecae": "Zarządzaj ustawieniami rozmiaru czcionki, koloru i tła. Te ustawienia będą mieć wpływ na wszystkie konta w serwisie X używane w tej przeglądarce.",
	"jc3fa0e2": "Wskaż języki, które pomogą nam dopasować wybierane dla Ciebie treści.",
