	"i931719e": "Numer zostanie usunięty z Twojego konta i nie będziesz już otrzymywać na ten numer powiadomień ani kodów logowania.",
	"j841d1f4": "Telefon został usunięty.",
	"fe8b565a": "Spowoduje to usunięcie numeru telefonu z danych tego konta, przez co nie będziesz już otrzymywać powiadomień w wiadomościach SMS z serwisu X. Spowoduje to również wyłączenie dwustopniowej weryfikacji logowania na tym koncie.",
	"hf45b8d4": "Spowoduje to usunięcie numeru telefonu z danych Twojego konta, przez co nie będziesz już otrzymywać powiadomień w wiadomościach SMS z serwisu X. Spowoduje to również wyłączenie dwustopniowej weryfikacji logowania za pomocą wiadomości SMS na tym koncie.",
	"bc262c2e": "Dodatkowe metody",
	"hc1a91da": "Kody zapasowe",
	"e4fed8f0": "Pobierz jednorazowe kody zapasowe, co umożliwi Ci zalogowanie się do serwisu X, jeśli nie będziesz mieć dostępu do żadnej z metod dwustopniowej weryfikacji logowania.",
	"b39c7b14": "Wyłączyć weryfikację logowania?",
	"a923fce6": "Jeśli wyłączysz dwustopniową weryfikację logowania, Twoje konto może być bardziej narażone na zagrożenia. Czy na pewno chcesz wyłączyć tę opcję?",
	"ff781e0a": "Wyłączyć tę opcję?",
	"c557ac30": "Czy na pewno chcesz wyłączyć tę metodę?",
	"d133464a": "Wyłączenie tej opcji spowoduje usunięcie dwustopniowej weryfikacji logowania na Twoim koncie. Czy na pewno chcesz ją wyłączyć?",
	"ee3a7bfa": "Wyłącz",
	"aa9139cc": "Prośby o weryfikację logowania",
	"jc22dd42": "Gdy się zalogujesz, otrzymasz w aplikacji serwisu X powiadomienie push. Zatwierdź je, aby uzyskać dostęp do swojego konta.",
	"e0d79de8": "Istnieje tylko jeden klucz bezpieczeństwa powiązany z Twoim kontem. Aby mieć pewność, że nie stracisz dostępu do swojego konta w przypadku utraty klucza, dodaj kolejny klucz lub zapisz kod dwustopniowej weryfikacji.",
	"ja6bbfa0": "Wczytywanie danych weryfikacji logowania",
	"c2570922": "Wiadomość SMS",
	"fba9483c": "Użyj telefonu komórkowego, aby odebrać wiadomość SMS z kodem uwierzytelniającym, który należy wprowadzić podczas logowania do serwisu X.",
	"ab61b41a": "Aplikacja uwierzytelniająca",
	"a67c7d68": "Korzystaj z mobilnej aplikacji uwierzytelniającej, aby otrzymywać kody weryfikacyjne, który należy wprowadzać podczas każdego logowania do serwisu X.",
	"h6d0d89c": "Klucz zabezpieczający",
	"b3e5c946": "Używaj klucza zabezpieczeń wkładanego do komputera lub synchronizowanego z urządzeniem mobilnym, gdy logujesz się do serwisu X. Będziesz potrzebować obsługiwanego urządzenia mobilnego lub przeglądarki internetowej.",
	"cd195528": "Dodaj nowy klucz bezpieczeństwa",
	"a1860ee8": "Hasło tymczasowe",
	"j45a2856": "Utwórz jednorazowe hasło tymczasowe do logowania się za pomocą usług zewnętrznych.",
	"d8612d9c": "Najpierw włącz opcję weryfikacji za pomocą wiadomości SMS lub aplikacji uwierzytelniającej",
	"e13d4468": "Aby ustanowić klucz bezpieczeństwa, musisz najpierw wybrać wiadomość SMS lub aplikację uwierzytelniającą jaką jedną z dwóch metod podwójnej weryfikacji logowania.",
	"c1d96d6a": "Dodano maksymalną liczbę kluczy",
	"gf91694e": "Aby dodać kolejny klucz, musisz usunąć jeden z dotychczasowych.",
	"j265ddb6": "Potwierdź adres e-mail",
	"a7cfdf1c": "Aby włączyć dwustopniową weryfikację logowania, musisz skojarzyć adres e-mail ze swoim kontem w serwisie X i potwierdzić, że naprawdę należy on do Ciebie.",
	"d7bfde1a": "Wygląda na to, że Twoje konto jest zawieszone. Dwustopniową weryfikację logowania można włączyć tylko w przypadku aktywnych kont.",
	"be65d410": "Korzystaj z dwustopniowej weryfikacji logowania za pomocą wiadomości SMS w ramach subskrypcji Premium",
	"gf205a76": "Tylko posiadacze subskrypcji Premium mogą korzystać z dwustopniowej weryfikacji logowania za pomocą wiadomości SMS. Podnieś poziom swojej subskrypcji, aby kontynuować.",
	"f66d24be": "Centrum Pomocy",
	"c8255462": "Ukryj etykietę konta zweryfikowanego za pomocą dokumentu tożsamości",
	"c6e731ee": "Ukryj etykietę konta zweryfikowanego za pomocą dokumentu tożsamości, aby użytkownicy nie mogli jej zobaczyć, gdy nacisną niebieski znaczek na stronie Twojego profilu.",
	"be582166": "Weryfikacja za pomocą dokumentu tożsamości może utrudnić podszywanie się pod Ciebie oraz sprawić, że Twój profil zostanie oznaczony etykietą konta zweryfikowanego za pomocą dokumentu tożsamości.",
	"b496bc94": "Analizujemy Twój dokument wydany przez organ państwowy. Będziemy Ci przekazywać powiadomienia dotyczące przebiegu tego procesu!\n\nPo zatwierdzeniu Twój profil zostanie oznaczony etykietą konta zweryfikowanego za pomocą dokumentu tożsamości, dzięki czemu inni użytkownicy będą wiedzieć, że Twoje konto zostało zweryfikowane w ten sposób.",
	"d8f5cce4": "Przekroczono limit liczby próśb o weryfikację. Spróbuj ponownie za 24 godziny.",
	"i8427a1e": "Tego konta nie można zweryfikować za pomocą dokumentu tożsamości. Obecnie jest to możliwe tylko w przypadku indywidualnych subskrybentów usługi Premium.",
	"cdc65e89": function(a){return a.title+" (opcjonalnie)"},
	"h05c1f28": "Zweryfikuj swoje konto, dostarczając dokument tożsamości wydany przez organ państwowy. Zazwyczaj zajmuje to ok. 5 minut.",
	"j8cfcc62": "Wyrażam zgodę na używanie przez firmy X i Au10tix obrazów przedstawiających mój dokument tożsamości oraz moją twarz, w tym wyodrębnionych z nich danych biometrycznych, w celu potwierdzenia mojej tożsamości, a także na potrzeby zapewnienia bezpieczeństwa i zabezpieczeń w serwisie X, w tym w celu zapobiegania naśladownictwu. Firma Au10tix może przechowywać takie dane nie dłużej niż przez 30 dni.",
	"c4930cb6": "Co będzie potrzebne:",
	"ac7bb0fe": "Przygotuj dokument tożsamości wydany przez organ państwowy",
	"c12ce69c": "Sprawdź, czy aparat w Twoim urządzeniu działa i nie jest zakryty",
