	"hccd9dbe": "W tym celu musisz wpisać swoje hasło.",
	"df1ddda4": "Etykiety lokalizacji dodane do wpisów nie będą już widoczne na stronie X.com ani w aplikacjach serwisu X dla systemów iOS i Android. Wprowadzanie tych aktualizacji może trochę potrwać.",
	"ed7fa034": "Usługi lokalizacji są obecnie wyłączone na tym urządzeniu. Możesz je włączyć w ustawieniach urządzenia.",
	"e80e4288": "Usuń wszystkie informacje o lokalizacji dołączone do Twoich wpisów",
