	"d4bb7e9c": "Postanowienia dotyczące programu Udział w dochodach z reklam przed filmami",
	"dc535dbe": "Złóż wniosek o dołączenie do programu Udział w dochodach z reklam wyświetlanych przed filmami, aby zarabiać więcej na swoich treściach publikowanych w serwisie X.",
	"eb6d9270": "Otrzymuj zapłatę za swoje treści",
	"a778472e": "Szczegóły:",
	"bde8446e": "Wybierz pozycję „Zaakceptuj i prześlij”, aby złożyć wniosek o dołączenie do programu Udział w dochodach z reklam.",
	"a415fd3a": "Zaakceptuj i prześlij",
	"fbba9725": "naszymi zasadami",
	"f3dd8c4a": "postanowieniami dotyczącymi programu Udział w dochodach z reklam oraz standardami monetyzacji dla twórców treści",
	"bcf3a9e6": "Zarządzaj ustawieniami, które pozwolą ograniczyć liczbę niepożądanych odpowiedzi.",
	"c048fd3a": "Ukrywaj odpowiedzi, które mogą zawierać niepożądane treści",
	"dab7dac4": "Odpowiedzi na Twoje wpisy, które mogą zawierać krzywdzący lub obraźliwy język, będą ukrywane i przenoszone tutaj. Inni użytkownicy wciąż będą mogli zobaczyć te odpowiedzi.",
	"c4c53b86": "Miej na uwadze to, że do wykrywania niepożądanych odpowiedzi stosujemy zautomatyzowane technologie, które mogą czasem rozpoznawać treści w błędny sposób.",
	"dca3d2ee": "Wyłączyć filtr odpowiedzi?",
	"fe440ff8": "Odfiltrowane odpowiedzi nie zostaną przywrócone w Twoich wpisach.",
