	"icfa5e8c": "Ogranicza animacje wyświetlane w aplikacji, w tym interakcje na żywo.",
	"ae41b002": "Ogranicza animacje wyświetlane w aplikacji, w tym interakcje na żywo. Twój system sygnalizuje potrzebę redukcji ruchu obrazu. Jeśli chcesz ponownie włączyć ruch obrazu, najpierw musisz go wyłączyć.",
	"h9d1cfae": "Otrzymuj przypomnienia o opisach zdjęć",
