	"g2a9bd3e": "Oznaczenie zautomatyzowanych kont",
	"dd9b3aae": "Czym jest zautomatyzowane konto?",
	"b80bdc40": "Zautomatyzowane konta są zaprogramowane do wykonywania za pośrednictwem interfejsu API serwisu X pewnych działań, takich jak publikowanie wpisów o warunkach pogodowych. Za tworzenie tych kont i zarządzanie nimi odpowiadają inne osoby w serwisie X.",
	"a01ac9b6": "Etykiety informują innych użytkowników, kto zarządza zautomatyzowanym kontem. Kiedy właściciel zautomatyzowanego konta powiąże z nim swoje konto zarządzające, w profilu zautomatyzowanego konta i w publikowanych z niego wpisach będzie widoczna etykieta.",
	"b989e1fe": "Czy muszę oznaczać swoje zautomatyzowane konta?",
	"i2d599aa": "Jak mam oznaczyć swoje zautomatyzowane konto?",
	"gd5bed72": "Utwórz konto zarządzające",
	"g6d44432": "Konto zarządzające jest kontem zarządzanym przez człowieka i wszystkie zautomatyzowane konta są mu podporządkowane.",
	"e20a69e8": "Powiąż swoje konto zarządzające i zautomatyzowane konto",
	"d2f88358": "Powiąż swoje konta na stronie Automatyzacja w swoich ustawieniach.",
	"e427f632": "Twoje konto otrzymało oznaczenie zautomatyzowanego konta!",
	"a4d7cffa": "Kiedy konta zostaną powiązane, zautomatyzowane konto otrzyma odpowiednie oznaczenie.",
	"a18d6a7d": "nowe zasady",
	"e9965c14": "często zadawanych pytań dotyczących oznaczania zautomatyzowanych kont",
	"ee78c192": "Co to jest konto PCF?",
	"c3f35e0c": "Konto PCF przedstawia inną osobę, grupę lub organizację w swoim profilu w celu prowadzenia dyskusji na jej temat, satyrycznego przedstawiania jej działalności lub udostępniania dotyczących jej informacji.",
	"d019b5fa": "Czy muszę oznaczyć etykietą swoje konto PCF?",
	"dd04f24e": "Tak. Etykieta PCF gwarantuje, że użytkownicy serwisu X nie będą mieć wątpliwości dotyczących Twojego konta, ponieważ ta etykieta będzie ich informować, że Twoje konto nie jest powiązane z tematem profilu. Konto nieoznaczone taką etykietą może naruszać Zasady dotyczące autentyczności.",
	"hb0f8bbc": "Jak mogę oznaczyć etykietą swoje konto PCF?",
	"g69acc5c": "Po prostu kliknij przycisk „Rozumiem”, a my użyjemy ustawień Twojego profilu, aby ustawić etykietę konta!",
	"d313d431": "Zasady dotyczące autentyczności",
	"a3f22d8e": "Wybierz, jakie powiadomienia o aktywnościach i zainteresowaniach oraz sugestie chcesz otrzymywać.",
	"bc20979a": "Serwis X oraz jego partnerzy używają plików cookie w celu dostarczania lepszej, bezpieczniejszej i szybszej usługi oraz w celu rozwijania swojej działalności. Niektóre pliki cookie są niezbędne do funkcjonowania naszych usług i ulepszania ich oraz zapewniania poprawności ich działania.",
	"ge06dadc": "Zezwalaj serwisowi X i jego partnerom na używanie plików cookie w celu prezentowania Ci reklam i przesyłania informacji zgodnych z Twoimi zainteresowaniami.",
	"he20de3a": "Nie zezwalaj serwisowi X na używanie plików cookie w celu zbierania dodatkowych danych służących do dostosowywania reklam i przesyłanych Ci informacji.",
	"g0ec0bec": "Dezaktywowano konto",
	"g89f4614": "Twoje konto jest nieaktywne",
	"f1768324": "Określ, w jaki sposób serwis X ma personalizować treści oraz zbierać i udostępniać pewne dane.",
	"ja94f34e": "Te ustawienia są ważne, kiedy jesteś wylogowany/a z przeglądarki lub urządzenia i nie mają zastosowania, gdy jesteś zalogowany/a.",
	"bd73f7e6": "Za pomocą tej opcji można włączyć lub wyłączyć wszystkie ustawienia strony.",
