	"hd43a218": "Osiągnięto dzienny limit dodanych uwag",
	"aaba8ed2": "Mając na uwadze zapewnienie wysokiej jakości uwag i ograniczenie rozpowszechniania spamu, uczestników programu obowiązuje dzienny limit uwag, które mogą oni dodać do Tweetów, wyrażany jako wartość pisarska. Spróbuj ponownie później.",
	"a67ed4d6": "Osiągnięto limit dodawania uwag do wpisów tego autora",
	"ic484166": "Aby zachować wysoką jakość uwag oraz zapobiegać spamowaniu, wprowadziliśmy limit liczby uwag, które możesz napisać w odniesieniu do danego autora wpisów w danym okresie. Ten limit jest oparty na opiniach innych osób wskazujących, jak bardzo pomocne były Twoje poprzednie uwagi dotyczące tego autora. Spróbuj ponownie później.",
