	"i7eb7900": "Twój dzienny limit zostanie zwiększony, jeśli będziesz zgłaszać żądania dotyczące wpisów, które następnie będą opatrywane pomocnymi uwagami.",
	"d1a3817e": "Pomaga to nagradzać osoby, które z powodzeniem znajdują potencjalnie wprowadzające w błąd wpisy, w odniesieniu do których warto podać dodatkowy kontekst.",
	"c031c77a": "Twój dzienny limit może zostać zmniejszony, jeśli będziesz zgłaszać zbyt wiele żądań dotyczących wpisów, które w opinii innych osób nie wymagają dodania uwagi.",
	"f87129d2": "Pomaga to zapobiegać spamowi i umożliwia twórcom uwag skoncentrowanie się na wpisach, do których warto dodać pomocne uwagi.",
	"jdd4a572": "Do Twojego konta musi być przypisany zweryfikowany numer telefonu",
	"i0f07c07": "Zweryfikuj swój numer telefonu",
	"i157c1a8": "To żądanie zostało usunięte.",
	"a9f4ca9c": "Uczestnicy programu Uwagi Społeczności widzą teraz Twoją uwagę",
	"eb8f7c0c": "Uczestnicy programu Birdwatch mogą teraz oceniać Twoją uwagę",
	"h87c6bd6": "Uczestnicy programu Birdwatch widzą teraz Twoją uwagę",
	"gc1a5bce": "Inni użytkownicy ocenią, czy Twoja uwaga jest pomocna",
	"i0e950ca": "Gdy Twoja uwaga zyska status pomocnej, będzie widoczna jako kontekst dla wszystkich osób wyświetlających wpis",
	"a047e800": "Twoja uwaga dostarcza innym uczestnikom programu Birdwatch dodatkowego kontekstu, który może być przydatny podczas oceniania uwag",
	"cec8a38c": "Gdy Twoja uwaga zyska status pomocnej, zwiększy się Twoja wartość pisarska.",
	"a377532e": "Gdy dostateczna liczba osób oceni tę uwagą jako pod różnymi względami pomocną, będzie ona widoczna jako kontekst dla wszystkich osób wyświetlających wpis",
	"d790fa4e": "Statusy uwag nie są ustalane według zasady większości głosów",
	"e90cda68": "Aby ustalić, które uwagi są pomocne dla szerokiej grupy użytkowników, bierzemy pod uwagę zgodność ocen uczestników programu, którzy czasem nie zgadzali się ze sobą w swoich wcześniejszych ocenach.",
	"j5a1d85a": "Zobacz swoją  uwagę",
	"b25b64d6": "Uwaga została przesłana!",
	"g1428d70": "Uwaga została przesłana!",
	"a4ec7004": "Co dalej?",
	"c4093274": "Uwagi Społeczności – co dzieje się po dodaniu uwagi?",
	"bc8746a6": "Oceń co najmniej jedną uwagę, zanim napiszesz nową.",
	"ce3c80b8": "Uwagi społeczności zależą od Twojej oceny, więc pomóż utrzymać ich wysoką jakość.",
	"fa6a075a": "Uwagi sugerują kontekst, który powinien być wyświetlany wraz z wpisem",
	"acb7ecae": "Uwagi wyjaśniające, dlaczego dodatkowy kontekst nie jest potrzebny",
	"d9a5fc06": "Oceń wpis",
	"b73cebd2": "Oceń wpis i uwagi",
	"ad8883f2": "Brak uwag dotyczących tego wpisu",
	"c7814e04": "Brak uwag sugerujących kontekst",
	"efd14e7a": "Wczytywanie uwag",
	"cc5d6270": "Współtwórcy zaproponowali uwagi społeczności dotyczące tego wpisu",
	"bcc14a68": "Uwagi Społeczności to program, w ramach którego chętne osoby mogą dodawać kontekst (uwagi) do wpisów, które ich zdaniem mogą wprowadzać innych użytkowników w błąd. Uwagi są następnie oceniane przez pozostałych uczestników programu, a jeśli uznają oni, że dana uwaga jest pomocna, stanie się ona widoczna w serwisie X jako kontekst wpisu. Jeśli daną uwagę oceniono jako pomocną, a Ty się z tym nie zgadzasz, możesz wnioskować o dodatkowy przegląd, podczas którego więcej osób oceni uwagę, co może zmienić jej status. ",
	"c21313ba": "Uwagi obecnie oznaczone jako niepomocne",
	"c2c40120": "Pokaż wszystkie uwagi",
	"ia596d40": "Uważasz, że trzeba coś ulepszyć?",
	"deff0bde": "Dodaj swoją uwagę",
	"i8e85ef8": "Dołącz do programu Uwagi Społeczności i zyskaj możliwość dodawania uwag oraz dostęp do innych funkcji, które pomagają nam lepiej zadbać o wysoką jakość informacji udostępnianych na platformie Twitter.",
	"af88892a": "Te uwagi zostały dodane przez uczestników programu Uwagi Społeczności, którzy sądzą, że ten wpis może wprowadzać w błąd i dlatego wymaga dodatkowego kontekstu.",
	"cf8a40a6": "Uwagi dodawane w ramach programu Uwagi Społeczności stają się widoczne dopiero wtedy, gdy zostaną ocenione jako pomocne przez dostateczną liczbę osób.",
	"g22c8c30": "Jeśli te uwagi zostaną oznaczone jako pomocne przez dostateczną liczbę uczestników programu (również tych, którzy zazwyczaj nie zgadzają się ze sobą w swoich ocenach), staną się one widoczne obok wpisów jako dodatkowy kontekst.",
	"jf04b084": "Te uwagi zostały dodane przez uczestników programu, którzy uważają, że wpis nie wprowadza w błąd i nie wymaga dodatkowego kontekstu.",
	"g5a72e98": "Te uwagi są widoczne w ramach programu Uwagi Społeczności jedynie jako dodatkowa informacja dla oceniających i nie będą wyświetlane jako dodatkowy kontekst wpisu, nawet gdy uzyskają status pomocnych.",
	"b8719c22": "Pomóż określić, czy wpisy są lubiane przez osoby patrzące z różnych perspektyw.",
	"jcdf97d4": "Co Ci się podoba w tym wpisie?",
	"d4d7b67e": "Co Ci się nie podoba w tym wpisie?",
	"ed5156fa": "Wystąpił błąd podczas zapisywania Twojej oceny. Spróbuj ponownie.",
