	"h5575012": "Zaakceptuj i prześlij",
	"f9171e52": "Ten wpis został polubiony przez osoby, które normalnie nie zgadzają się ze sobą, ale aktualnie mamy mało danych wejściowych.",
	"j0f9919a": "Twoja ocena nie będzie mieć negatywnego wpływu na wpis, ale może pomóc w pozytywnym wyróżnianiu powszechnie lubianych wpisów.",
