	"fab9ea84": "Zasugeruj ulepszenie",
	"d4ed0166": "Opcjonalnie możesz zasugerować ulepszenia, dzięki którym uwaga będzie bardziej pomocna, takie jak udostępnienie linku do bardziej przekonującego źródła bądź zasugerowanie bardziej zrozumiałego sformułowania.",
	"bb036f62": "Sugestie są nowe, więc nie pokazujemy ich jeszcze innym współtwórcom w ramach zapewniania jakości. Zgodnie z założeniami w przyszłości mają one pomagać piszącym w dopracowywaniu uwag i proponowaniu lepszych uwag.",
