	"db08295e": "Dołączysz?",
	"ha275800": "Wygląda na to, że nie uczestniczysz w pilotażowym programie Uwagi Społeczności. Dołącz, aby wspólnie z nami zadbać o rzetelność informacji publikowanych w serwisie X.",
	"ce0a213a": "Aby utworzyć uwagę, wybierz ikonę Uwagi Społeczności z menu dowolnego wpisu. Twoje uwagi będą widoczne w tym miejscu.",
	"c87f3cf8": "Uwaga",
	"a5b19492": "Ta uwaga nie jest dostępna",
	"c21d1b2a": "Uwagi zyskują status pomocnych lub niepomocnych, gdy pojawia się zgodna ocena dostatecznej liczby uczestników programu, w tym osób, które mogły się ze sobą nie zgadzać we wcześniejszych ocenach. Pozwala to upewnić się, że uwagi są pomocne dla szerokiej grupy użytkowników i zapobiec stosowaniu jednostronnych ocen.",
