	"if2e01ee": "Kilka powiadomień w miesiącu",
	"fdaeaab8": "Wystąpił błąd podczas zapisywania Twoich ustawień. Spróbuj ponownie.",
	"db4e443a": "Twoje ustawienia zostały zapisane.",
	"dc11636c": "Języki, które znasz",
	"fae059c6": "Opuść program Uwagi Społeczności",
	"ed37123a": "Opuszczasz program Uwagi Społeczności",
	"c1a554a2": "Poniżej znajdują się ważne informacje:",
	"j59355fe": "Nie będziesz mieć możliwości pisania nowych uwagi społeczności.",
	"c23420ec": "Nie będziesz otrzymywać powiadomień z programu Uwagi Społeczności, chyba że będą związane z Twoją aktywnością w serwisie X.",
	"c76031ee": "Twój anonimowy profil uczestnika programu Uwagi Społeczności oraz przesłane uprzednio materiały pozostaną dostępne publicznie. Nadal będziesz mieć możliwość wyświetlania i usuwania swoich uwag.",
	"be4f9106": "Możesz dołączyć ponownie po upływie 90 dni.",
	"c62b12b4": "Informacje o programie Uwagi Społeczności",
	"hf68e810": "Uwagi Społeczności to program, który ma nam pomóc podnieść jakość udostępnianych informacji. Dzięki niemu użytkownicy serwisu X mogą wspólnie dodawać pomocne uwagi do wpisów, które mogłyby wprowadzać innych użytkowników w błąd.",
	"jdb52860": "Współtwórcy dodają uwagi i je oceniają",
	"c104025c": "Uczestnicy programu to osoby korzystające z serwisu X, takie jak Ty, które zgłosiły się do programu pilotażowego, aby pisać i oceniać uwagi. Im więcej osób zaangażuje się w ten program, tym lepsze wyniki uzyskamy.",
	"j7872b8c": "Przy wpisach są wyświetlane tylko uwagi uznane przez innych za pomocne",
	"fb59415e": "Aby uwagi były wyświetlane publicznie jako kontekst przy wpisach, muszą zostaną ocenione jako pomocne z różnych punktów widzenia przez wystarczającą liczbę osób. Pomaga to uniknąć treści, które są stronnicze lub stanowią manipulację, i ułatwia znalezienie uwag pomocnych dla wielu osób.",
	"f9a44022": "To nie firma X decyduje o tym, które uwagi są wyświetlane — robią to użytkownicy",
	"gdf4fbb2": "Firma X nie dodaje, nie ocenia ani nie moderuje uwag (jeśli nie naruszają one Zasad serwisu X). Użytkownicy podejmują decyzje wspólnie. Wierzymy, że to sprawiedliwa i skuteczna metoda udostępniania rzetelnych informacji.",
	"cc720e6a": "U podstaw programu Uwagi Społeczności leży przejrzystość danych",
	"j2fcd33a": "Dane zawierają treści dodane do",
	"d4a6b322": "Wszystkie uwagi i informacje dodawane w ramach programu Uwagi Społeczności publikowane są tu codziennie, dzięki czemu użytkownicy mają pełen dostęp do wszystkich danych oraz mogą szybko identyfikować problemy i podejmować odpowiednie działania. Poznaj wszystkie opcje, jakie oferuje program Uwagi Społeczności.",
	"c359263a": "Dowiedz się, w jaki sposób wykorzystywać i analizować dane dotyczące programu Uwagi Społeczności ",
	"b8a27fe2": "naszego przewodnika",
