	"ad37d536": "Postanowienia dotyczące przekazywania nazw użytkownika",
	"e760074a": "Przejmij nieużywaną nazwę użytkownika lub zamień ją na własną",
	"j003ef92": "Kup od firmy X nieaktywne nazwy użytkownika dla siebie lub swoich powiązanych kont albo zamień używane nazwy użytkownika na inne, które już posiadasz.",
	"d57a8e42": "Ta usługa jest dostępna wyłącznie w ramach programu Zweryfikowanie Organizacje, a jej używanie wiąże się z dodatkowymi kosztami na każdą nazwę użytkownika. Te koszty zaczynają się od 10 000 USD.",
	"hef473cc": "Ta usługa jest dostępna wyłącznie w ramach subskrypcji Premium Business, a jej używanie wiąże się z dodatkowymi kosztami na każdą nazwę użytkownika. Te koszty zaczynają się od 10 000 USD.",
	"h9367bd6": "Prześlij zapytanie dotyczące nazwy użytkownika",
	"a6a62e7e": "Rozpocznij proces, odpowiadając na kilka pytań przy użyciu naszego zautomatyzowanego bota pomocy technicznej.",
	"e5912290": "Rozpoczynanie zapytania dotyczącego nazwy użytkownika",
	"c2e24f66": "Poszukaj wiadomości z działu pomocy technicznej w dolnym rogu ekranu.",
	"c94f514e": "Zapytanie dotyczące nazwy użytkownika zostało rozpoczęte",
	"cf60d152": "Wypełnij krótki kwestionariusz w oknie czatu, aby przesłać zapytanie dotyczące nazwy użytkownika.",
	"f06b124e": "Często zadawane pytania",
	"h677fdcc": "W jaki sposób są wyceniane nazwy użytkownika?",
	"a55b39aa": "Głównie na podstawie liczby znaków oraz powszechności słów. Ceny zaczynają się od 10 tys. USD i mogą sięgać nawet 500 tys. USD.",
	"d46bcb3a": "Skąd mam wiedzieć, czy nazwa użytkownika jest dostępna do zakupu?",
	"c6bcf72c": "Wyślij nam żądanie, używając przycisku Rozpocznij, a my poinformujemy Cię, czy dana nazwa użytkownika jest dostępna.",
	"d478604c": "Czy mogę kupić nazwę użytkownika w imieniu innej firmy?",
	"c09f8cd2": "Nie. Firmy mogą kupować nazwy użytkownika tylko w imieniu swoich powiązanych podmiotów, które są autentycznie połączone z ich działalnością.",
	"d814f020": "Jak wygląda proces sprzedaży? Jak długo trwa sprzedaż?",
	"f600b6f0": "Zażądaj zakupu lub zamiany nazwy użytkownika, używając przycisku Rozpocznij. W ciągu 3 dni roboczych otrzymasz odpowiedź z informacjami o dostępności i cenach. W ciągu 1–2 dni od wykonania płatności przekażemy nazwę użytkownika na wybrane przez Ciebie konto. Opcjonalnie możemy przenieść starą nazwę użytkownika na inne należące do Ciebie konto.",
	"i8debc4a": "Czy oferujecie rabaty w przypadku zakupu wielu nazw użytkownika?",
	"c5199f3c": "Tak, w zależności od liczby kupowanych nazw użytkownika i łącznej wielkości oferty.",
	"c20f923e": "Posiadam znak towarowy — czy to coś zmienia?",
	"b2fd4c15": "Zasady dotyczące znaków towarowych",
	"a690746e": "Korzystaj z priorytetowej pomocy technicznej",
	"he2dc9b0": "Skontaktuj się z nami, wysyłając nazwę użytkownika swojej organizacji oraz szczegóły żądania.",
	"ed85ca9e": "Skontaktuj się z nami, wysyłając nazwę użytkownika swojej firmy oraz szczegóły żądania.",
	"e5e6479e": "Wyślij nam wiadomość e-mail zawierającą nazwę użytkownika organizacji oraz szczegóły zapytania, aby skorzystać z najszybszej pomocy technicznej.",
	"dd0855d0": "Wyślij nam wiadomość e-mail zawierającą nazwę użytkownika firmy oraz szczegóły zapytania, aby skorzystać z najszybszej pomocy technicznej.",
	"ica8392a": "Gdy otrzymamy Twoje żądanie, przeanalizujemy je i nadamy mu priorytet zgodnie z jego pozycją w kolejności odebranych żądań.",
	"ed37e36e": "Ważne: brak nazwy użytkownika organizacji lub użycie prywatnego adresu e-mail może spowodować opóźnienia w przetwarzaniu Twojego żądania.",
	"b8e25b96": "Ważne: brak nazwy użytkownika firmy lub użycie prywatnego adresu e-mail może spowodować opóźnienia w przetwarzaniu Twojego żądania.",
