	"b2138d0f": function(){return ["Subskrybując, akceptujesz nasze ",". Subskrypcje są odnawiane automatycznie do momentu anulowania, tak jak opisano w ",". ",". Aby uniknąć dodatkowych opłat, anuluj subskrypcję w dowolnym momencie co najmniej 24 godziny przed odnowieniem. Podniesienie poziomu spowoduje, że Twoja bieżąca subskrypcja i skojarzone z nią funkcje zostaną natychmiast przełączone do nowego poziomu subskrypcji. Natychmiast zostanie Ci naliczona opłata równa cenie nowego poziomu, ale pozostała proporcjonalna część z Twojego aktualnego cyklu rozliczeniowego zostanie wykorzystana na potrzeby opłacania dzisiejszej łącznej opłaty. Nie otrzymasz zwrotu kosztów żadnej części poprzedniej subskrypcji, chyba że jest to wymagane przez prawo."]},
	"c2255911": function(){return ["Subskrybując, akceptujesz nasze ",". Subskrypcje są odnawiane automatycznie do momentu anulowania, tak jak opisano w ",". ",". Aby uniknąć dodatkowych opłat, anuluj subskrypcję w dowolnym momencie co najmniej 24 godziny przed odnowieniem. Obniżenie poziomu spowoduje, że Twoja bieżąca subskrypcja będzie aktywna do następnego cyklu rozliczeniowego, w którym rozpocznie się Twoja nowa subskrypcja. Począwszy od następnego cyklu rozliczeniowego będą Ci naliczane opłaty w wysokości ceny nowego poziomu."]},
	"e647175f": function(){return ["Subskrybując, akceptujesz nasze ",". Subskrypcje są odnawiane automatycznie do momentu anulowania, tak jak opisano w ",". ",". Aby uniknąć dodatkowych opłat, anuluj subskrypcję w dowolnym momencie co najmniej 24 godziny przed odnowieniem. W przypadku przełączenia nadal będziesz mieć możliwość korzystania z funkcji skojarzonych z Twoim poziomem. Natychmiast zostanie Ci naliczona opłata równa cenie nowego planu rocznego, a pozostała proporcjonalna część salda Twojego miesięcznego cyklu rozliczeniowego zostanie wykorzystana na potrzeby opłacenia dzisiejszej łącznej opłaty."]},
	"eaccb9c9": function(){return ["Subskrybując, akceptujesz nasze ",". Subskrypcje są odnawiane automatycznie do momentu anulowania, tak jak opisano w ",". ",". Aby uniknąć dodatkowych opłat, anuluj subskrypcję w dowolnym momencie co najmniej 24 godziny przed odnowieniem. W przypadku przełączenia nadal będziesz mieć możliwość korzystania z funkcji skojarzonych z Twoim poziomem. Natychmiast zostanie Ci naliczona opłata równa cenie miesięcznej aktualnie używanego poziomu, ale pozostała proporcjonalna część z Twojej płatności rocznej będzie wykorzystywana na potrzeby opłacania opłat miesięcznych, dopóki się nie wyczerpie."]},
