	"h7f3e309": function(){return ["Opłata w wysokości ceny dawanej w prezencie subskrypcji jest pobierana w chwili zakupu i nie podlega zwrotowi. Ta subskrypcja jest jednorazowa, nie można jej zamienić na inną ani połączyć z inną ofertą, a także nie ma ona wartości pieniężnej. Subskrypcja zostanie aktywowana, gdy zespół serwisu X wykona przegląd i przypisze ją do odbiorcy, który musi potwierdzić nasze "," oraz polityki. Jeśli odbiorca nie będzie spełniał wymagań dotyczących uprawnienia do subskrypcji, anuluje subskrypcję albo odrzuci nasze postanowienia i polityki, nie będziesz mieć możliwości ponownego wykorzystania prezentu ani odzyskania jego kosztów. Mogą zostać naliczone odpowiednie podatki. Postanowienia mogą ulec zmianie. ","."]},
